mapper.select:
SELECT d.*, e.name as director_name, p.name as parent_name, (SELECT COUNT(*) FROM employee emp WHERE emp.department_id = d.id AND emp.delflag = 0 AND emp.employment_status = 1) as employee_count, (SELECT COUNT(*) FROM department child WHERE child.parentId = d.id AND child.delflag = 0) as children_count FROM department d LEFT JOIN employee e ON d.directorId = e.id AND e.delflag = 0 LEFT JOIN department p ON d.parentId = p.id AND p.delflag = 0 WHERE d.delflag = 0
AND d.id = #{query.id}
AND d.parentId = #{query.parentId}
AND d.name LIKE CONCAT('%', #{query.name}, '%')
AND d.depNo = #{query.depNo}
AND d.directorId = #{query.directorId}
AND d.gradeid = #{query.gradeid}
AND d.fiiale = #{query.fiiale}
AND d.status = #{query.status}
AND d.status = 1
AND (d.name LIKE CONCAT('%', #{query.keyword}, '%') OR d.depNo LIKE CONCAT('%', #{query.keyword}, '%') OR d.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND d.parentId = 0
ORDER BY d.sort_order ASC, d.id ASC

SELECT d.*, e.name as director_name, (SELECT COUNT(*) FROM employee emp WHERE emp.department_id = d.id AND emp.delflag = 0 AND emp.employment_status = 1) as employee_count, (SELECT COUNT(*) FROM department child WHERE child.parentId = d.id AND child.delflag = 0) as children_count FROM department d LEFT JOIN employee e ON d.directorId = e.id AND e.delflag = 0 WHERE d.delflag = 0 AND d.parentId = #{parentId}
AND d.status = 1
ORDER BY d.sort_order ASC, d.id ASC

SELECT COUNT(*) FROM employee e WHERE e.delflag = 0 AND e.employment_status = 1
AND e.department_id IN ( WITH RECURSIVE dept_tree AS ( SELECT id FROM department WHERE id = #{departmentId} AND delflag = 0 UNION ALL SELECT d.id FROM department d INNER JOIN dept_tree dt ON d.parentId = dt.id WHERE d.delflag = 0 ) SELECT id FROM dept_tree )
AND e.department_id = #{departmentId}

SELECT COUNT(*) > 0
FROM department
WHERE depNo = #{depNo} 
    AND delflag = 0

    AND id != #{excludeId}

SELECT COUNT(*) > 0
FROM department
WHERE name = #{name} 
    AND parentId = #{parentId}
    AND delflag = 0

    AND id != #{excludeId}

